"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["96318"],{3457(a){a.exports=JSON.parse('{"id":"F507","slug":"news-move-significance","name":"Reading the News: Is This Move Unusual?","subject":"Practical Skills & Capstone","section":"Putting It Together","topic":"Follow financial news critically","level":"Beginner","aliases":["follow financial news critically","headline move","z-score of a daily move","how often does this happen"],"formula":{"latex":"z=\\\\frac{r}{\\\\sigma_{d}},\\\\quad P(|Z|\\\\ge|z|)=2\\\\,(1-\\\\Phi(|z|)),\\\\quad \\\\text{Days per event}\\\\approx\\\\frac{1}{P}","also":[],"text":"Size of the move in standard deviations = daily return / typical daily volatility; Chance of a move at least this large in either direction under a normal distribution = 2 x (1 - normal cumulative of |z|); About how many trading days between such moves = 1 / that chance; Real markets have fatter tails, so large moves happen more often than a normal curve suggests"},"symbols":[{"symbol":"r","meaning":"Return on the day in the headline","unit":"percent"},{"symbol":"sigma_d","meaning":"Typical daily volatility (annual volatility / square root of 252)","unit":"percent"}],"when_to_use":"Use it to put a dramatic headline in context. A fall of 3% may be an ordinary week for one stock and a rare event for another. Compare the move with the asset\'s own typical swings. Be careful: the normal curve understates how often extreme days occur, so treat the frequency as a lower bound.","worked_example":{"problem":"A stock fell 6.2% in a day. Its typical daily volatility is 1.4%.","inputs":{"r":-6.2,"s":1.4},"steps":[{"label":"Size of the move in standard deviations","working":"-0.062 / 0.014","value":"-4.43"},{"label":"Chance of a move at least this big (two-sided)","working":null,"value":"0.0009%"},{"label":"Trading days per such event","working":"1 / 9.48593e-06","value":"105,419"},{"label":"Years per event (252 days a year)","working":"105419 / 252","value":"418.3"},{"label":"Unusual? (1 = beyond 3 standard deviations)","working":null,"value":"1"}],"answer":"The move is -4.43 standard deviations. Under a normal distribution a move this large happens with a chance of 0.0009% on any day, about once every 105,419 trading days, or once in 418.3 years. The headline is 1 (1 = unusual, beyond 3 standard deviations)."},"calculator":{"available":true,"inputs":[{"id":"r","label":"Return on the day","unit":"%","type":"number","default":-6.2,"hint":""},{"id":"s","label":"Typical daily volatility","unit":"%","type":"number","default":1.4,"hint":""}],"checks":[{"expr":"s>0","message":"Daily volatility must be above zero."}],"steps":[{"id":"z","label":"Size of the move in standard deviations","expr":"r/s","format":"num2"},{"id":"p","label":"Chance of a move at least this big (two-sided)","expr":"2*(1-normcdf(abs(z)))","format":"pct4"},{"id":"days","label":"Trading days per such event","expr":"1/p","format":"num0"},{"id":"yrs","label":"Years per event (252 days a year)","expr":"days/252","format":"num1"},{"id":"flag_","label":"Unusual? (1 = beyond 3 standard deviations)","expr":"1 if abs(z)>3 else 0","format":"num0"}],"results":["z","p","yrs","flag_"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"z":-4.428571428571429,"p":9.485930392294506e-6,"days":105419.28505108025,"yrs":418.33049623444543,"flag_":1}},"finder":{"finds":"How unusual a market move is for that asset","needs":"Return on the day and typical daily volatility"},"related":[{"slug":"z-score","name":"Z-Score"},{"slug":"forecast-calibration","name":"Forecast Calibration and Brier Score"},{"slug":"var-parametric","name":"Value at Risk: Parametric (Variance-Covariance)"}],"related_ids":["F047","F421","F378"],"group":"Modern finance and practice","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>z</mi><mo>=</mo><mfrac><mi>r</mi><msub><mi>\u03C3</mi><mi>d</mi></msub></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>P</mi><mo stretchy=\\"false\\">(</mo><mi mathvariant=\\"normal\\">\u2223</mi><mi>Z</mi><mi mathvariant=\\"normal\\">\u2223</mi><mo>\u2265</mo><mi mathvariant=\\"normal\\">\u2223</mi><mi>z</mi><mi mathvariant=\\"normal\\">\u2223</mi><mo stretchy=\\"false\\">)</mo><mo>=</mo><mn>2</mn><mtext>\u2009</mtext><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi mathvariant=\\"normal\\">\u03A6</mi><mo stretchy=\\"false\\">(</mo><mi mathvariant=\\"normal\\">\u2223</mi><mi>z</mi><mi mathvariant=\\"normal\\">\u2223</mi><mo stretchy=\\"false\\">)</mo><mo stretchy=\\"false\\">)</mo><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Days\xa0per\xa0event</mtext><mo>\u2248</mo><mfrac><mn>1</mn><mi>P</mi></mfrac></mrow><annotation encoding=\\"application/x-tex\\">z=\\\\frac{r}{\\\\sigma_{d}},\\\\quad P(|Z|\\\\ge|z|)=2\\\\,(1-\\\\Phi(|z|)),\\\\quad \\\\text{Days per event}\\\\approx\\\\frac{1}{P}</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"rational-bubble-growth","name":"Rational Bubble: Required Growth and Survival"},"next":{"slug":"real-return","name":"Real Return (Inflation-Adjusted)"},"lesson":null,"total":522}')}}]);